#pragma once

// The ways the shell dresses a stock control from the theme: a label, a
// text field, and an OrcaSlicer Button. Widgets the shell paints itself
// (HeaderButton, the swatch cells) read ShellTheme directly; these recipes
// exist so a wxStaticText or a Button never carries a hand-typed font, radius
// or colour of its own.

#include "ShellTheme.hpp"

class Button;
class wxColour;
class wxStaticText;
class wxTextCtrl;

namespace Slic3r::GUI::JusPrin {

// Font from the role, foreground as given: the caller names the colour because
// the same role reads in text_primary, text_secondary or a status colour.
void style_label(wxStaticText& label, const ShellTheme& theme, TextRole role, const wxColour& foreground);

// Body font on the canvas surface in the primary text colour.
void style_text_field(wxTextCtrl& field, const ShellTheme& theme, const ShellPalette& palette);

// Size, padding, radius and font from one of the component.button recipes;
// colours from the palette's secondary action. This is the fork's counterpart
// to Button::SetStyle(ButtonStyle::Regular, type), built from tokens instead
// of the teal tables.
void style_button(Button& button, const ShellTheme& theme, const ShellPalette& palette, const ButtonRecipe& recipe);

// The same geometry recipe with the semantic primary action state table.
void style_primary_button(Button& button, const ShellTheme& theme, const ShellPalette& palette,
                          const ButtonRecipe& recipe);

// The same geometry recipe as a link (component.button.link): the primary
// action colour on no fill or border, underlined under the pointer, with the
// focus ring as its only edge.
void style_link_button(Button& button, const ShellTheme& theme, const ShellPalette& palette, const ButtonRecipe& recipe);

} // namespace Slic3r::GUI::JusPrin
#pragma once

#include <wx/colour.h>
#include <wx/font.h>

#include <array>
#include <optional>
#include <string>

namespace Slic3r::GUI::JusPrin {

// Semantic colors for one appearance mode, resolved from
// resources/jusprin/ui/design-tokens.json. That file is the authoritative
// source; this struct only carries the values the shell consumes.
struct ShellPalette
{
    wxColour surface_canvas;
    wxColour surface_subtle;
    wxColour surface_raised;
    // A row under the pointer or the keyboard inside a menu or popover.
    wxColour surface_raised_hover;
    wxColour surface_selected;
    wxColour text_primary;
    wxColour text_secondary;
    wxColour border_subtle;
    wxColour border_strong;
    wxColour border_focus;
    wxColour action_primary;
    wxColour action_primary_hover;
    wxColour action_primary_pressed;
    wxColour action_primary_text;
    wxColour action_disabled;
    wxColour action_disabled_text;
    wxColour status_warning;
    wxColour status_success;
    wxColour status_success_on_action;
    wxColour status_danger;
    wxColour overlay_scrim;
    // elevation.subtle's and elevation.medium's shadow colours, with this
    // mode's opacity as alpha.
    wxColour elevation_subtle;
    wxColour elevation_medium;
    // The 3D axis colours, the same in both modes because they name the same
    // handles: a red X, a green Y and a blue Z.
    wxColour axis_x;
    wxColour axis_y;
    wxColour axis_z;
};

// The text roles the token file defines under typography.roles.
enum class TextRole { PageTitle, Section, Body, BodyBold, BodySmall, BodySmallBold, Label, LabelBold, Metadata, MetadataBold };
constexpr size_t kTextRoleCount = 10;

// The numbers behind one text role. Sizes are DIP; weight is 400 or 700.
struct TypeStyle
{
    int size{0};
    int line_height{0};
    int weight{0};
};

// One entry of component.button. Each recipe names only some of these
// fields; the ones it leaves out stay 0.
struct ButtonRecipe
{
    int min_width{0};
    int width{0};
    int height{0};
    int min_height{0};
    int padding_x{0};
    int padding_y{0};
    int icon_size{0};
    int radius{0};
    std::optional<TextRole> text_role;
};

struct ButtonMetrics
{
    ButtonRecipe compact;
    ButtonRecipe window;
    ButtonRecipe choice;
    ButtonRecipe parameter;
    ButtonRecipe icon;
    // The design system's 26 DIP icon target: the canvas tool strip and the
    // reset button in a form row, which stands at the field's height.
    ButtonRecipe icon_compact;
    ButtonRecipe expanded;
    ButtonRecipe secondary;
    // The design system's Button/SecondarySmall, 28 DIP.
    ButtonRecipe secondary_small;
    // Button/Link: text in the primary action colour, no fill or border.
    ButtonRecipe link;
    ButtonRecipe primary;
};

struct ChipMetrics      { int height{0}; int radius{0}; };
struct MenuRowMetrics   { int height{0}; int radius{0}; int side_inset{0}; };
// Rows sit inside the popover's border, so a full-width row never covers it.
struct PopoverMetrics   { int padding_y{0}; int row_gap{0}; int radius{0}; int border_width{0}; int width{0}; };
struct StatusRowMetrics { int height{0}; };
struct AgentPaneMetrics {
    int width{0};
    int min_width{0};
    int workspace_min_width{0};
    int resize_handle_width{0};
    int resize_handle_line_width{0};
};
// A colour cell of the filament menu: the swatch, the gaps around the grid,
// and how a cell is drawn at rest and as the slot's current colour.
struct SwatchMetrics
{
    int size{0};
    int radius{0};
    int gap{0};                // between cells
    int caption_gap{0};        // under the grid's caption
    int inset{0};              // swatch inside its cell, at rest
    int current_inset{0};      // ... when it is the slot's colour
    int ring_width{0};         // edge at rest
    int current_ring_width{0}; // ring of the slot's colour
    int glyph_width{0};        // the "+" cell's stroke
};
// The chip's row of filament-slot dots.
struct SlotDotMetrics
{
    int size{0};
    int compact_size{0}; // when more slots are in use than fit at full size
    int gap{0};
    int compact_gap{0};
    int label_gap{0};    // from the last dot to the label
    int faded_alpha{0};  // 0-255: a slot the plate does not print with
};
// The keyboard focus ring every focusable control draws.
struct FocusMetrics     { int width{0}; int offset{0}; };
// The Plates / Project pane's geometry, from component.leftPane. Heights and
// paddings are DIP, taken from the pane's Figma frames; each row is a box whose
// padding and gap are named here so the painted row and the frame agree.
struct LeftPaneMetrics
{
    int width{0};
    int min_width{0};
    int padding_y{0};
    int tab_height{0};
    int tab_indicator_height{0};
    int list_padding_y{0};
    int row_gap{0};
    int row_padding_x{0};
    int row_padding_y{0};
    int plate_row_height{0};
    int object_row_height{0};
    int object_indent{0};
    int glyph_size{0};
    int plate_gap{0};
    int object_gap{0};
    int summary_indent{0};
    int summary_padding_bottom{0};
    int add_plate_padding_top{0};
    int add_plate_padding_bottom{0};
    int add_plate_padding_x{0};
    int add_plate_button_height{0};
};

// Home's printers column, which the printer conversation takes over while it
// is open, so the two are the same width.
struct PrinterCardMetrics { int column_width{0}; int radius{0}; };

// JusPrin's Preferences window; its page reads the rest of the group.
struct PreferencesMetrics { int width{0}; int height{0}; };

// File › Import › Import from OrcaSlicer…'s window.
struct OrcaImportMetrics { int width{0}; int height{0}; };

// The startup splash: a square window, the version line's and the bar's top,
// the bar's track and moving segment, and how long one sweep across takes.
struct SplashMetrics
{
    int size{0};
    int version_top{0};
    int bar_top{0};
    int bar_width{0};
    int bar_segment_width{0};
    int bar_sweep_ms{0};
};

// Help › About JusPrin's window.
struct AboutMetrics { int width{0}; int lockup_height{0}; int help_label_width{0}; int copied_ms{0}; };

// A drop shadow's geometry; its colour differs by mode and lives in ShellPalette.
struct ElevationMetrics { int offset_x{0}; int offset_y{0}; int blur{0}; int spread{0}; };

// The numeric tool panel's parts: a value field with an optional unit, the
// coordinate-space select, the uniform-scale checkbox, one row of the form,
// and the panel that holds them.
struct FieldMetrics     { int height{0}; int radius{0}; int padding_x{0}; int min_width{0};
                          std::optional<TextRole> text_role; std::optional<TextRole> unit_text_role; };
struct SelectMetrics    { int height{0}; int radius{0}; int padding_x{0}; int chevron_size{0};
                          std::optional<TextRole> text_role; };
struct CheckboxMetrics  { int size{0}; int radius{0}; int glyph_size{0}; int label_gap{0};
                          std::optional<TextRole> text_role; };
struct FormRowMetrics   { int height{0}; int gap{0}; int label_width{0}; std::optional<TextRole> text_role; };
struct ToolPanelMetrics { int padding{0}; int row_gap{0}; int radius{0}; int min_width{0};
                          std::optional<TextRole> title_text_role; };
// The round severity or state marker: a printer's state, a report finding's severity.
struct StatusDotMetrics  { int size{0}; };
// The dashed outline of an absence: a printer that is not connected, a
// filament colour nobody chose. Dash and gap run along the ring.
struct DashedRingMetrics { int dash{0}; int gap{0}; };
// The header row of a collapsible group in a list: a section of the Check
// print report, a settings group.
struct GroupHeaderMetrics { int height{0}; };
// The print-issue bubble and list on the Prepare canvas. Everything else they
// use (padding, radii, the two buttons) comes from the shared scales and recipes.
struct PrintIssueMetrics { int bubble_width{0}; int list_width{0}; };

// Geometry from the token file's dimension and component sections. Every
// value is DIP; callers wrap it in FromDIP().
struct ShellMetrics
{
    // The design system's radius scale, under its own names.
    int radius_small{0};
    int radius_medium{0};
    int radius_large{0};
    int radius_chip{0};
    int radius_full{0};

    // The spacing scale, named by its step: space_2 is dimension.space["2"].
    // space_half is the half step, dimension.space["0.5"]: only the gap
    // between a row's main line and the detail line under it.
    int space_half{0};
    int space_1{0};
    int space_2{0};
    int space_3{0};
    int space_4{0};
    int space_5{0};
    int space_6{0};
    int space_8{0};
    int space_10{0};
    int space_12{0};

    ElevationMetrics elevation_medium;

    ButtonMetrics    button;
    FieldMetrics     field;
    SelectMetrics    select;
    CheckboxMetrics  checkbox;
    StatusDotMetrics status_dot;
    DashedRingMetrics dashed_ring;
    GroupHeaderMetrics group_header;
    FormRowMetrics   form_row;
    ToolPanelMetrics tool_panel;
    PrintIssueMetrics print_issues;
    ChipMetrics      chip;
    MenuRowMetrics   menu_row;
    PopoverMetrics   popover;
    StatusRowMetrics status_row;
    AgentPaneMetrics agent_pane;
    LeftPaneMetrics  left_pane;
    SwatchMetrics    swatch;
    SlotDotMetrics   slot_dot;
    FocusMetrics     focus;
    PrinterCardMetrics  printer_card;
    PreferencesMetrics  preferences;
    OrcaImportMetrics   orca_import;
    SplashMetrics       splash;
    AboutMetrics        about;
    // component.progress.height: the track every progress bar shares.
    int                 progress_height{0};
};

class ShellTheme
{
public:
    // Loads both semantic palettes, the metrics and the text roles from the
    // packaged token file. Throws std::runtime_error when the file is missing
    // or malformed so the caller can fall back to the standard Orca
    // presentation. Needs no wx initialisation.
    static ShellTheme load_from_resources();

    const ShellPalette& palette(bool dark) const { return dark ? m_dark : m_light; }
    const ShellMetrics& metrics() const { return m_metrics; }
    const TypeStyle&    type_style(TextRole role) const { return m_type_styles[size_t(role)]; }

    // The wxFont for a role, built once on first use through OrcaSlicer's
    // Label::sysFont so it carries the same face as the rest of the
    // application, then sized so the role's DIP size is its em on every
    // platform (sysFont's own point scaling rounds the token off on Windows
    // and Linux). Requires wx to be initialised.
    const wxFont& font(TextRole role) const;

    // typography.code: the system monospace face, only for code and IDs such
    // as a build's commit hash. Requires wx to be initialised.
    const wxFont& code_font() const;

private:
    ShellPalette m_light;
    ShellPalette m_dark;
    ShellMetrics m_metrics;
    std::array<TypeStyle, kTextRoleCount> m_type_styles{};
    mutable std::array<wxFont, kTextRoleCount> m_fonts{};
    TypeStyle m_code_style;
    mutable wxFont m_code_font;
};

} // namespace Slic3r::GUI::JusPrin

// First: slic3r/GUI/I18N.hpp defines _L only while the _ macro is still
// undefined, so it has to precede any header that brings one in.
#include "slic3r/GUI/I18N.hpp"

#include "ServerSheet.hpp"

#include "HeaderControls.hpp"
#include "ShellRecipes.hpp"
#include "ShellTheme.hpp"

#include "slic3r/GUI/GUI_App.hpp"
#include "slic3r/GUI/JusPrin/Agent/AgentConfiguration.hpp"
#include "slic3r/GUI/JusPrin/Brand/BrandPalette.hpp"
#include "slic3r/GUI/Widgets/Button.hpp"
#include "slic3r/GUI/Widgets/WebView.hpp"
#include "slic3r/Utils/Http.hpp"

#include <boost/log/trivial.hpp>
#include <nlohmann/json.hpp>

#include <wx/dcbuffer.h>
#include <wx/display.h>
#include <wx/panel.h>
#include <wx/sizer.h>
#include <wx/stattext.h>
#include <wx/webview.h>

#include <algorithm>

namespace Slic3r::GUI::JusPrin {

namespace {

// How long the link and the page together may take before the sheet says the
// page could not be loaded; WebKit's own limit is over a minute.
constexpr int kLoadDeadlineMs   = 20000;
// How long to wait before trying again to destroy a closed sheet whose web
// view was installing its script handler (see release()).
constexpr int kReleaseRetryMs   = 50;
constexpr int kHeaderHeightDip  = 48;

ServerSheet* g_sheet = nullptr;

wxString page_title(const std::string& page)
{
    return page == "billing" ? _L("Billing and usage") : _L("Credits and plans");
}

// The server's answer to POST /v2/web_link, on the GUI thread: a URL, or empty
// when the server could not be reached or refused (its sign-in has ended).
// Signed out, the app asks without a token, and the link is to Credits and
// plans as someone without an account sees it.
void request_web_link(const std::string& page, const std::string& from, std::function<void(std::string)> done)
{
    AppConfig*        config = wxGetApp().app_config;
    const std::string token  = Agent::cloud_account_token(config);
    auto finish = [done = std::move(done)](std::string url) {
        wxGetApp().CallAfter([done, url = std::move(url)] { done(url); });
    };
    Http http = Http::post(Agent::cloud_web_link_url(config));
    if (!token.empty())
        http.header("Authorization", "Bearer " + token);
    http.header("Content-Type", "application/json")
        .header("Accept", "application/json")
        .set_post_body(nlohmann::json{{"page", page}, {"from", from}}.dump())
        .tls_verify(true)
        .timeout_connect(10)
        .timeout_max(30)
        .on_complete([finish](std::string body, unsigned status) {
            const nlohmann::json answer = nlohmann::json::parse(body, nullptr, false);
            std::string          url = status == 200 && answer.is_object() ? answer.value("url", std::string()) : std::string();
            if (url.empty())
                BOOST_LOG_TRIVIAL(warning) << "JusPrin page link answered " << status;
            finish(std::move(url));
        })
        .on_error([finish](std::string, std::string error, unsigned status) {
            BOOST_LOG_TRIVIAL(warning) << "JusPrin page link failed: " << status << " " << error;
            finish({});
        })
        .perform();
}

} // namespace

void ServerSheet::open(wxWindow* parent, const std::string& page, const std::string& from, std::function<void()> closed)
{
    // Without the design tokens there is no sheet to draw; the page opens in
    // the person's browser, signed in the same way.
    const ShellTheme* theme = brand_theme();
    if (theme == nullptr) {
        request_web_link(page, from, [closed](const std::string& url) {
            if (!url.empty())
                wxLaunchDefaultBrowser(wxString::FromUTF8(url));
            if (closed)
                closed();
        });
        return;
    }
    // Nothing outside the sheet takes a click while it is open; this is for
    // a second request the same moment.
    if (g_sheet != nullptr) {
        g_sheet->show_page(page, from);
        return;
    }
    auto* sheet = new ServerSheet(parent, *theme);
    g_sheet     = sheet;
    sheet->show_page(page, from);
    sheet->ShowModal();
    g_sheet = nullptr;
    // The opener reads the account again: a purchase may have gone through.
    if (closed)
        closed();
    sheet->release();
}

ServerSheet* ServerSheet::current() { return g_sheet != nullptr && !g_sheet->m_closing ? g_sheet : nullptr; }

ServerSheet::ServerSheet(wxWindow* parent, const ShellTheme& theme)
    : wxDialog(parent, wxID_ANY, wxEmptyString, wxDefaultPosition, wxDefaultSize, wxDEFAULT_DIALOG_STYLE | wxRESIZE_BORDER)
    , m_theme(theme)
{
    SetName("Server sheet");
    const ShellPalette& palette = theme.palette(wxGetApp().dark_mode());
    SetBackgroundColour(palette.surface_raised);

    // One child for release() to destroy, holding the title row, the page and
    // what shows in its place.
    m_body = new wxPanel(this);
    m_body->SetBackgroundColour(palette.surface_raised);
    wxWindow* header = build_header();
    m_view           = WebView::CreateWebView(m_body, wxEmptyString);

    m_status        = new wxPanel(m_body);
    m_status_title  = new wxStaticText(m_status, wxID_ANY, wxEmptyString);
    m_status_detail = new wxStaticText(m_status, wxID_ANY, _L("Check your internet connection, then try again."));
    m_retry         = new Button(m_status, _L("Try again"));
    m_retry->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) { load(); });
    m_status->SetBackgroundColour(palette.surface_canvas);
    style_label(*m_status_title, theme, TextRole::BodyBold, palette.text_primary);
    style_label(*m_status_detail, theme, TextRole::Body, palette.text_secondary);
    style_primary_button(*m_retry, theme, palette, theme.metrics().button.primary);
    auto* block = new wxBoxSizer(wxVERTICAL);
    block->Add(m_status_title, 0, wxALIGN_CENTER_HORIZONTAL);
    block->Add(m_status_detail, 0, wxALIGN_CENTER_HORIZONTAL | wxTOP, FromDIP(8));
    block->Add(m_retry, 0, wxALIGN_CENTER_HORIZONTAL | wxTOP, FromDIP(24));
    auto* centred = new wxBoxSizer(wxVERTICAL);
    centred->AddStretchSpacer();
    centred->Add(block, 0, wxALIGN_CENTER_HORIZONTAL | wxALL, FromDIP(48));
    centred->AddStretchSpacer();
    m_status->SetSizer(centred);

    auto* body = new wxBoxSizer(wxVERTICAL);
    body->Add(header, 0, wxEXPAND);
    body->Add(m_view, 1, wxEXPAND);
    body->Add(m_status, 1, wxEXPAND);
    m_body->SetSizer(body);
    auto* sizer = new wxBoxSizer(wxVERTICAL);
    sizer->Add(m_body, 1, wxEXPAND);
    SetSizer(sizer);

    if (m_view != nullptr) {
        m_view->Bind(wxEVT_WEBVIEW_NAVIGATING, &ServerSheet::on_navigating, this);
        m_view->Bind(wxEVT_WEBVIEW_LOADED, &ServerSheet::on_loaded, this);
        m_view->Bind(wxEVT_WEBVIEW_ERROR, &ServerSheet::on_error, this);
        // A link the page opens in a new window goes to the person's browser:
        // the sheet holds one page.
        m_view->Bind(wxEVT_WEBVIEW_NEWWINDOW, [](wxWebViewEvent& event) { wxLaunchDefaultBrowser(event.GetURL()); });
        // WebView::CreateWebView gives every page the app's message bridge; a
        // server page's messages end here and reach nothing.
        m_view->Bind(wxEVT_WEBVIEW_SCRIPT_MESSAGE_RECEIVED, [](wxWebViewEvent&) {});
    }
    Bind(wxEVT_CLOSE_WINDOW, [this](wxCloseEvent&) { close(); });
    Bind(wxEVT_CHAR_HOOK, [this](wxKeyEvent& event) {
        if (event.GetKeyCode() == WXK_ESCAPE)
            close();
        else
            event.Skip();
    });
    Bind(wxEVT_TIMER, [this](wxTimerEvent&) { if (!m_closing) set_state(State::Failed); }, m_load_deadline.GetId());
    Bind(wxEVT_TIMER, [this](wxTimerEvent&) { release(); }, m_release_timer.GetId());

    // As wide as the boards draw it, and never taller than the screen it is on.
    wxSize size = FromDIP(wxSize(760, 760));
    if (const int display = wxDisplay::GetFromWindow(parent); display != wxNOT_FOUND)
        size.SetHeight(std::min(size.GetHeight(), wxDisplay(display).GetClientArea().GetHeight() * 9 / 10));
    SetSize(size);
    CentreOnParent();
    wxGetApp().UpdateDlgDarkUI(this);
}

ServerSheet::~ServerSheet()
{
    *m_alive = false;
    if (g_sheet == this)
