        dc.SetPen(*wxTRANSPARENT_PEN);
        dc.SetBrush(wxBrush(m_progress_bg_color));
        dc.DrawRectangle(progress_rc);

        const int fill_width = progress_rc.GetWidth() * m_progress * 0.01;
        if (fill_width > 0) {
