    void SetText(const wxString& text, int progress)
    {
        int calc_progress = std::max(m_progress, std::clamp(progress, 0, 100));
        if (m_text_action != text || m_progress != calc_progress){
            m_text_action = text;
            m_progress = calc_progress;
