def track(seg_left=None, animated=False):
    """The 4 DIP progress track with the moving segment; seg_left None draws no segment."""
    seg = ""
    if seg_left is not None:
        cls = ' class="jp-splash-seg"' if animated else ''
        seg = (f'<div data-n="Moving segment"{cls} style="position:absolute;left:{seg_left}px;top:0;width:{SEG_W}px;height:100%;'
               f'border-radius:var(--radius-full);background:var(--action-primary)"></div>')
    return (f'<div data-n="Activity bar" role="progressbar" aria-label="Loading" style="box-sizing:border-box;position:relative;'
