236	void AboutWindow::show_copy_label(bool copied)
237	{
238	    const ShellPalette& palette = m_theme.palette(GUI_App::dark_mode());
239	    // The button's icon is a bitmap Button draws at its scaled size, so it is
240	    // rasterized at the screen's pixels and told their scale.
241	    const double scale  = GetContentScaleFactor();
242	    const int    pixels = std::max(1, int(std::lround(FromDIP(kButtonIconDip) * scale)));
243	    wxBitmap     icon   = lucide_bitmap(copied ? "check" : "copy", pixels, palette.text_primary);
244	    icon.SetScaleFactor(scale);
245	    m_copy->SetLabel(copied ? _L("Copied") : _L("Copy version"));
246	    m_copy->SetIcon(icon);
247	    m_copy->GetParent()->Layout();
248	}
